LedgerBridge::IPCStableHashFunction LedgerBridge::MessageToMethodInfo_(mojo::Message& message) {
#if !BUILDFLAG(IS_FUCHSIA)
  switch (static_cast<messages::LedgerBridge>(message.name())) {
    case messages::LedgerBridge::kUnlock: {
      return &LedgerBridge::Unlock_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kGetDeviceName: {
      return &LedgerBridge::GetDeviceName_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kEthGetAccount: {
      return &LedgerBridge::EthGetAccount_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kEthSignTransaction: {
      return &LedgerBridge::EthSignTransaction_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kEthSignPersonalMessage: {
      return &LedgerBridge::EthSignPersonalMessage_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kEthSignEip712Message: {
      return &LedgerBridge::EthSignEip712Message_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kSolGetAccount: {
      return &LedgerBridge::SolGetAccount_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kSolSignTransaction: {
      return &LedgerBridge::SolSignTransaction_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kFilGetAccount: {
      return &LedgerBridge::FilGetAccount_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kFilSignTransaction: {
      return &LedgerBridge::FilSignTransaction_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kBtcGetAccount: {
      return &LedgerBridge::BtcGetAccount_Sym::IPCStableHash;
    }
    case messages::LedgerBridge::kBtcSignTransaction: {
      return &LedgerBridge::BtcSignTransaction_Sym::IPCStableHash;
    }
  }
#endif  // !BUILDFLAG(IS_FUCHSIA)
  return nullptr;
}


const char* LedgerBridge::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (static_cast<messages::LedgerBridge>(message.name())) {
      case messages::LedgerBridge::kUnlock:
            return "Receive brave_wallet::mojom::LedgerBridge::Unlock";
      case messages::LedgerBridge::kGetDeviceName:
            return "Receive brave_wallet::mojom::LedgerBridge::GetDeviceName";
      case messages::LedgerBridge::kEthGetAccount:
            return "Receive brave_wallet::mojom::LedgerBridge::EthGetAccount";
      case messages::LedgerBridge::kEthSignTransaction:
            return "Receive brave_wallet::mojom::LedgerBridge::EthSignTransaction";
      case messages::LedgerBridge::kEthSignPersonalMessage:
            return "Receive brave_wallet::mojom::LedgerBridge::EthSignPersonalMessage";
      case messages::LedgerBridge::kEthSignEip712Message:
            return "Receive brave_wallet::mojom::LedgerBridge::EthSignEip712Message";
      case messages::LedgerBridge::kSolGetAccount:
            return "Receive brave_wallet::mojom::LedgerBridge::SolGetAccount";
      case messages::LedgerBridge::kSolSignTransaction:
            return "Receive brave_wallet::mojom::LedgerBridge::SolSignTransaction";
      case messages::LedgerBridge::kFilGetAccount:
            return "Receive brave_wallet::mojom::LedgerBridge::FilGetAccount";
      case messages::LedgerBridge::kFilSignTransaction:
            return "Receive brave_wallet::mojom::LedgerBridge::FilSignTransaction";
      case messages::LedgerBridge::kBtcGetAccount:
            return "Receive brave_wallet::mojom::LedgerBridge::BtcGetAccount";
      case messages::LedgerBridge::kBtcSignTransaction:
            return "Receive brave_wallet::mojom::LedgerBridge::BtcSignTransaction";
    }
  } else {
    switch (static_cast<messages::LedgerBridge>(message.name())) {
      case messages::LedgerBridge::kUnlock:
            return "Receive reply brave_wallet::mojom::LedgerBridge::Unlock";
      case messages::LedgerBridge::kGetDeviceName:
            return "Receive reply brave_wallet::mojom::LedgerBridge::GetDeviceName";
      case messages::LedgerBridge::kEthGetAccount:
            return "Receive reply brave_wallet::mojom::LedgerBridge::EthGetAccount";
      case messages::LedgerBridge::kEthSignTransaction:
            return "Receive reply brave_wallet::mojom::LedgerBridge::EthSignTransaction";
      case messages::LedgerBridge::kEthSignPersonalMessage:
            return "Receive reply brave_wallet::mojom::LedgerBridge::EthSignPersonalMessage";
      case messages::LedgerBridge::kEthSignEip712Message:
            return "Receive reply brave_wallet::mojom::LedgerBridge::EthSignEip712Message";
      case messages::LedgerBridge::kSolGetAccount:
            return "Receive reply brave_wallet::mojom::LedgerBridge::SolGetAccount";
      case messages::LedgerBridge::kSolSignTransaction:
            return "Receive reply brave_wallet::mojom::LedgerBridge::SolSignTransaction";
      case messages::LedgerBridge::kFilGetAccount:
            return "Receive reply brave_wallet::mojom::LedgerBridge::FilGetAccount";
      case messages::LedgerBridge::kFilSignTransaction:
            return "Receive reply brave_wallet::mojom::LedgerBridge::FilSignTransaction";
      case messages::LedgerBridge::kBtcGetAccount:
            return "Receive reply brave_wallet::mojom::LedgerBridge::BtcGetAccount";
      case messages::LedgerBridge::kBtcSignTransaction:
            return "Receive reply brave_wallet::mojom::LedgerBridge::BtcSignTransaction";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

