void LedgerBridgeUIHandlerProxy::BindLedgerBridge(
    ::mojo::PendingRemote<LedgerBridge> in_bridge) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send brave_wallet::mojom::LedgerBridgeUIHandler::BindLedgerBridge", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("bridge"), in_bridge,
                        "<value of type ::mojo::PendingRemote<LedgerBridge>>");
   });
#endif

  const bool kExpectsResponse = false;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;

  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::LedgerBridgeUIHandler::kBindLedgerBridge), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::brave_wallet::mojom::internal::LedgerBridgeUIHandler_BindLedgerBridge_Params_Data> params(
          message);
  params.Allocate();

  
  mojo::internal::Serialize<mojo::InterfacePtrDataView<::brave_wallet::mojom::LedgerBridgeInterfaceBase>>(
    in_bridge,
    &params->bridge,
    &params.message());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(!mojo::internal::IsHandleOrInterfaceValid(params->bridge)),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
    "invalid bridge in LedgerBridgeUIHandler.BindLedgerBridge request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(LedgerBridgeUIHandler::Name_);
  message.set_method_name("BindLedgerBridge");
#endif
  // This return value may be ignored as false implies the Connector has
  // encountered an error, which will be visible through other means.
  ::mojo::internal::SendMojoMessage(*receiver_, message);
}

