void LedgerBridgeServiceProxy::BindLedgerBridge(
    ::mojo::PendingReceiver<LedgerBridge> in_bridge) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send brave_wallet::mojom::LedgerBridgeService::BindLedgerBridge", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("bridge"), in_bridge,
                        "<value of type ::mojo::PendingReceiver<LedgerBridge>>");
   });
#endif

  const bool kExpectsResponse = false;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;

  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::LedgerBridgeService::kBindLedgerBridge), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::brave_wallet::mojom::internal::LedgerBridgeService_BindLedgerBridge_Params_Data> params(
          message);
  params.Allocate();

  
  mojo::internal::Serialize<mojo::InterfaceRequestDataView<::brave_wallet::mojom::LedgerBridgeInterfaceBase>>(
    in_bridge,
    &params->bridge,
    &params.message());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(!mojo::internal::IsHandleOrInterfaceValid(params->bridge)),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
    "invalid bridge in LedgerBridgeService.BindLedgerBridge request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(LedgerBridgeService::Name_);
  message.set_method_name("BindLedgerBridge");
#endif
  // This return value may be ignored as false implies the Connector has
  // encountered an error, which will be visible through other means.
  ::mojo::internal::SendMojoMessage(*receiver_, message);
}

// static
bool LedgerBridgeServiceStubDispatch::Accept(
    LedgerBridgeService* impl,
    mojo::Message* message) {
  switch (static_cast<messages::LedgerBridgeService>(message->header()->name)) {
    case messages::LedgerBridgeService::kBindLedgerBridge: {
      DCHECK(message->is_serialized());
      internal::LedgerBridgeService_BindLedgerBridge_Params_Data* params =
          reinterpret_cast<internal::LedgerBridgeService_BindLedgerBridge_Params_Data*>(
              message->mutable_payload());
      

      // Validation for LedgerBridgeService.0
      bool success = true;
      ::mojo::PendingReceiver<LedgerBridge> p_bridge{};
      LedgerBridgeService_BindLedgerBridge_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_bridge =
            input_data_view.TakeBridge<decltype(p_bridge)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            LedgerBridgeService::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->BindLedgerBridge(        
        std::move(p_bridge));
      return true;
    }
  }
  return false;
}

